ALTER TABLE public.content_items ADD COLUMN IF NOT EXISTS review_status text NOT NULL DEFAULT 'draft'; ALTER TABLE public.content_items ADD COLUMN IF NOT EXISTS source_report_id uuid; ALTER TABLE public.content_items ADD COLUMN IF NOT EXISTS reviewed_at timestamptz; GRANT UPDATE ON public.content_items TO authenticated; CREATE POLICY "Owners review their content" ON public.content_items FOR UPDATE TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid()); CREATE FUNCTION public.enforce_competitor_limit() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.kind='competitor' THEN PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id::text,0)); IF (SELECT count(*) FROM public.growth_records WHERE user_id=NEW.user_id AND kind='competitor' AND payload->>'site'=NEW.payload->>'site' AND id<>NEW.id)>=3 THEN RAISE EXCEPTION 'Only three competitors per website are allowed'; END IF; END IF; RETURN NEW; END $$; CREATE TRIGGER competitor_limit BEFORE INSERT OR UPDATE ON public.growth_records FOR EACH ROW EXECUTE FUNCTION public.enforce_competitor_limit(); CREATE UNIQUE INDEX competitor_site_unique ON public.growth_records(user_id,(payload->>'site'),(payload->>'url')) WHERE kind='competitor';